'use client';

import Link from 'next/link';
import { mockSignificantChanges } from '@/data/kpiData';
import { AnomalyBadge } from './AnomalyBadge';

interface ChangeItemProps {
  change: typeof mockSignificantChanges[0];
}

function ChangeItem({ change }: ChangeItemProps) {
  const isNegative = change.changePct < 0;
  const arrow = isNegative ? '↓' : '↑';

  return (
    <article className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700 p-5 transition-shadow hover:shadow-sm">
      <div className="flex items-start justify-between gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-3 flex-wrap">
            <h3 className="text-slate-900 dark:text-slate-100 font-medium">{change.metric}</h3>
            <span className={`text-sm font-medium tabular-nums ${isNegative ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'}`}>
              {arrow} {Math.abs(change.changePct).toFixed(1)}%
            </span>
          </div>
          <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">{change.region}</p>
          <p className="mt-2 text-sm text-slate-600 dark:text-slate-300">{change.description}</p>
        </div>
        <div className="flex items-center gap-3 shrink-0">
          <AnomalyBadge severity={change.severity} anomaly={change.severity !== 'normal'} />
          <Link
            href={`/investigate/${change.metric.toLowerCase().replace(/\s+/g, '-')}`}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md text-sm font-medium text-white bg-red-600 hover:bg-red-700 transition-colors focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 dark:focus:ring-offset-slate-900"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            Investigate
          </Link>
        </div>
      </div>
    </article>
  );
}

export function SignificantChanges() {
  const highImpactChanges = mockSignificantChanges.filter(c => c.severity !== 'normal');

  if (!highImpactChanges.length) return null;

  return (
    <section aria-labelledby="significant-changes-heading" className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 id="significant-changes-heading" className="text-lg font-semibold text-slate-900 dark:text-slate-100">
          Recent Significant Changes
        </h2>
        <span className="text-sm text-slate-500 dark:text-slate-400">
          {highImpactChanges.length} anomaly{highImpactChanges.length !== 1 ? 's' : ''} detected
        </span>
      </div>
      <div className="space-y-4">
        {highImpactChanges.map((change) => (
          <ChangeItem key={change.id} change={change} />
        ))}
      </div>
    </section>
  );
}