'use client';

import { KPIData } from '@/data/kpiData';
import { formatValue, formatChangePct, getTrendDirection } from '@/data/kpiData';
import { Sparkline } from './Sparkline';
import { AnomalyBadge } from './AnomalyBadge';
import { InvestigateButton } from './InvestigateButton';

interface KPICardProps {
  data: KPIData;
}

export function KPICard({ data }: KPICardProps) {
  const direction = getTrendDirection(data.changePct);
  const isNegative = data.changePct < 0;
  const isPositive = data.changePct > 0;

  return (
    <article className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700 p-6 transition-shadow hover:shadow-md">
      <div className="flex items-start justify-between gap-4 mb-4">
        <div className="min-w-0 flex-1">
          <h3 className="text-slate-500 dark:text-slate-400 text-sm font-medium truncate">{data.name}</h3>
          <p className="mt-1 text-3xl font-semibold text-slate-900 dark:text-slate-100 tabular-nums">
            {formatValue(data.value, data.unit)}
          </p>
        </div>
        <AnomalyBadge severity={data.severity} anomaly={data.anomaly} />
      </div>

      <div className="flex items-end justify-between gap-4 mb-4">
        <div className="flex items-baseline gap-2">
          <span className={`text-sm font-medium tabular-nums ${isNegative ? 'text-red-600 dark:text-red-400' : isPositive ? 'text-green-600 dark:text-green-400' : 'text-slate-500 dark:text-slate-400'}`}>
            {formatChangePct(data.changePct)}
          </span>
          <span className="text-xs text-slate-500 dark:text-slate-400">{data.label}</span>
        </div>
      </div>

      <div className="mb-4">
        <Sparkline data={data.trend} currentValue={data.value} severity={data.severity} />
      </div>

      <InvestigateButton metricId={data.id} severity={data.severity} anomaly={data.anomaly} />
    </article>
  );
}