'use client';

import { Severity } from '@/data/kpiData';

interface AnomalyBadgeProps {
  severity: Severity;
  anomaly?: boolean;
  className?: string;
}

const severityConfig: Record<Severity, { label: string; className: string }> = {
  normal: { label: 'NORMAL', className: 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300' },
  high: { label: 'HIGH IMPACT', className: 'bg-red-50 text-red-700 dark:bg-red-900/30 dark:text-red-400' },
  critical: { label: 'CRITICAL', className: 'bg-red-100 text-red-800 dark:bg-red-900/40 dark:text-red-300' },
};

export function AnomalyBadge({ severity, anomaly = false, className = '' }: AnomalyBadgeProps) {
  if (!anomaly && severity === 'normal') {
    return (
      <span
        className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${severityConfig.normal.className} ${className}`}
      >
        {severityConfig.normal.label}
      </span>
    );
  }

  const config = severityConfig[severity];
  return (
    <span
      className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium ${config.className} ${className}`}
    >
      {severity === 'critical' && (
        <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20" aria-hidden="true">
          <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
        </svg>
      )}
      {config.label}
    </span>
  );
}