'use client';

import { KPIData } from '@/data/kpiData';

interface SparklineProps {
  data: number[];
  currentValue: number;
  severity: KPIData['severity'];
  className?: string;
}

export function Sparkline({ data, currentValue, severity, className = '' }: SparklineProps) {
  if (!data.length) return null;

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;

  const width = 120;
  const height = 40;
  const padding = 2;

  const points = data.map((value, index) => {
    const x = padding + (index / (data.length - 1)) * (width - 2 * padding);
    const y = height - padding - ((value - min) / range) * (height - 2 * padding);
    return `${x},${y}`;
  }).join(' ');

  const currentIndex = data.length - 1;
  const currentX = padding + (currentIndex / (data.length - 1)) * (width - 2 * padding);
  const currentY = height - padding - ((currentValue - min) / range) * (height - 2 * padding);

  const strokeColor = severity === 'high' || severity === 'critical'
    ? '#dc2626'
    : severity === 'normal'
    ? '#64748b'
    : '#f59e0b';

  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      className={`shrink-0 ${className}`}
      aria-hidden="true"
    >
      <defs>
        <linearGradient id="sparkline-gradient" x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor={strokeColor} stopOpacity="0.3" />
          <stop offset="100%" stopColor={strokeColor} stopOpacity="0.8" />
        </linearGradient>
      </defs>
      <polyline
        fill="none"
        stroke="url(#sparkline-gradient)"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        points={points}
      />
      <circle
        cx={currentX}
        cy={currentY}
        r={4}
        fill={strokeColor}
        stroke="#ffffff"
        strokeWidth={2}
      />
    </svg>
  );
}